mod parser;
mod command;
mod runner;
mod help;
mod base64;
mod export;
mod compgen;
mod completions;

use std::env;
use std::process::ExitCode;

const VERSION: &str = "1.23.0";

const HELP: &str = "A bash cli framework, also a bash-based command runner - https://github.com/sigoden/argc

USAGE:
    argc --argc-eval <FILE> <ARGS~>            Use `eval \"$(argc --argc-eval \"$0\" \"$@\")\"`
    argc --argc-create <RECIPES~>              Create a boilerplate argcfile
    argc --argc-run <FILE> <ARGS~>             Run an argc-based script
    argc --argc-build <FILE> <OUTPATH?>        Generate bashscript without argc dependency
    argc --argc-mangen <FILE> <OUTDIR>         Generate man pages
    argc --argc-completions <SHELL> <CMDS>     Generate shell completion scripts
    argc --argc-compgen <SHELL> <FILE> <ARGS>  Generate completion candidates
    argc --argc-export <FILE>                  Export command line definitions as json
    argc --argc-parallel <FILE> <ARGS~>        Run functions in parallel
    argc --argc-script-path                    Print current argcfile path
    argc --argc-shell-path                     Print current shell path
    argc --argc-help                           Print help information
    argc --argc-version                        Print version information
";

fn main() -> ExitCode {
    let args: Vec<String> = env::args().collect();
    match run(&args) {
        Ok(code) => ExitCode::from(code),
        Err(e) => {
            eprintln!("{}", e);
            ExitCode::from(1)
        }
    }
}

fn run(args: &[String]) -> Result<u8, String> {
    if args.len() == 1 {
        return default_run();
    }
    let cmd = &args[1];
    match cmd.as_str() {
        "--argc-version" => {
            println!("argc {}", VERSION);
            Ok(0)
        }
        "--argc-help" => {
            println!("{}", HELP);
            Ok(0)
        }
        "--argc-shell-path" => {
            println!("{}", shell_path());
            Ok(0)
        }
        "--argc-script-path" => {
            match find_argcfile() {
                Some(p) => { println!("{}", p); Ok(0) }
                None => Err("Argcfile not found.".into())
            }
        }
        "--argc-eval" => {
            if args.len() < 3 {
                return Err("argc --argc-eval requires FILE".into());
            }
            let file = &args[2];
            let rest: Vec<String> = args[3..].to_vec();
            runner::run_eval(file, &rest)
        }
        "--argc-run" => {
            if args.len() < 3 {
                return Err("argc --argc-run requires FILE".into());
            }
            let file = &args[2];
            let rest: Vec<String> = args[3..].to_vec();
            runner::run_script(file, &rest)
        }
        "--argc-create" => {
            let recipes: Vec<String> = args[2..].to_vec();
            runner::create_argcfile(&recipes)
        }
        "--argc-export" => {
            if args.len() < 3 {
                return Err("argc --argc-export requires FILE".into());
            }
            export::export_file(&args[2])
        }
        "--argc-compgen" => {
            if args.len() < 5 {
                return Err("argc --argc-compgen requires SHELL FILE ARGS".into());
            }
            compgen::compgen(&args[2], &args[3], &args[4..])
        }
        "--argc-completions" => {
            if args.len() < 3 {
                return Err("argc --argc-completions requires SHELL".into());
            }
            completions::completions(&args[2], &args[3..])
        }
        _ => {
            // Default: try find Argcfile
            default_run()
        }
    }
}

fn default_run() -> Result<u8, String> {
    match find_argcfile() {
        Some(p) => {
            // Run the argcfile
            let args: Vec<String> = env::args().skip(1).collect();
            runner::run_script(&p, &args)
        }
        None => Err("Argcfile not found, try `argc --argc-help` for help.".into())
    }
}

pub fn find_argcfile() -> Option<String> {
    let names = ["Argcfile.sh", "Argcfile"];
    let mut dir = env::current_dir().ok()?;
    loop {
        for n in &names {
            let p = dir.join(n);
            if p.exists() {
                return Some(p.to_string_lossy().to_string());
            }
            // Case-insensitive
            if let Ok(entries) = std::fs::read_dir(&dir) {
                for entry in entries.flatten() {
                    let name = entry.file_name();
                    let s = name.to_string_lossy();
                    if s.eq_ignore_ascii_case(n) {
                        return Some(entry.path().to_string_lossy().to_string());
                    }
                }
            }
        }
        if !dir.pop() { break; }
    }
    None
}

fn shell_path() -> String {
    if let Ok(v) = env::var("ARGC_SHELL_PATH") { return v; }
    "/usr/bin/bash".to_string()
}
