const CHARSET: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

pub fn encode(data: &[u8]) -> String {
    let mut out = String::with_capacity((data.len() + 2) / 3 * 4);
    let mut i = 0;
    while i + 3 <= data.len() {
        let b0 = data[i]; let b1 = data[i+1]; let b2 = data[i+2];
        out.push(CHARSET[(b0 >> 2) as usize] as char);
        out.push(CHARSET[(((b0 & 0x3) << 4) | (b1 >> 4)) as usize] as char);
        out.push(CHARSET[(((b1 & 0xf) << 2) | (b2 >> 6)) as usize] as char);
        out.push(CHARSET[(b2 & 0x3f) as usize] as char);
        i += 3;
    }
    match data.len() - i {
        1 => {
            let b0 = data[i];
            out.push(CHARSET[(b0 >> 2) as usize] as char);
            out.push(CHARSET[((b0 & 0x3) << 4) as usize] as char);
            out.push('=');
            out.push('=');
        }
        2 => {
            let b0 = data[i]; let b1 = data[i+1];
            out.push(CHARSET[(b0 >> 2) as usize] as char);
            out.push(CHARSET[(((b0 & 0x3) << 4) | (b1 >> 4)) as usize] as char);
            out.push(CHARSET[((b1 & 0xf) << 2) as usize] as char);
            out.push('=');
        }
        _ => {}
    }
    out
}
