// Parser for argc comment tags and script structure.

use crate::command::*;
use std::path::Path;

pub fn parse_script(file: &str, content: &str) -> Result<Command, String> {
    let script_name = Path::new(file)
        .file_stem()
        .map(|s| s.to_string_lossy().into_owned())
        .unwrap_or_else(|| "argc".to_string());

    let mut root = Command::default();
    root.name = script_name.clone();

    // State-based parser. Collect tags that apply to the "next" @cmd or root.
    let mut pending_cmd: Option<Command> = None; // currently collecting subcommand
    let mut in_root = true;
    let mut prev_blank = true;

    // A buffer of tags waiting for the next function definition (for root or cmd)
    // Actually argc works line-by-line: @describe at top sets root, @cmd starts a new sub, following tags belong to that sub until a function definition.

    let lines: Vec<&str> = content.split('\n').collect();
    let mut i = 0;
    while i < lines.len() {
        let raw = lines[i];
        let line = raw.trim_start();

        // Is it a comment tag?
        if let Some(tag) = parse_tag_line(line) {
            if tag.name == "cmd" {
                // Flush pending subcommand (discard; it was never assigned a function)
                // Start a new one
                let mut new_cmd = Command::default();
                new_cmd.describe = tag.rest.to_string();
                pending_cmd = Some(new_cmd);
                in_root = false;
            } else {
                apply_tag(&mut root, &mut pending_cmd, in_root, &tag)?;
            }
            i += 1;
            prev_blank = false;
            continue;
        }

        // A blank or non-comment line: might be a function definition
        let trimmed = raw.trim();
        if trimmed.is_empty() {
            prev_blank = true;
            i += 1;
            continue;
        }
        if raw.trim_start().starts_with('#') {
            // non-tag comment; ignore but do not reset pending cmd
            i += 1;
            prev_blank = false;
            continue;
        }

        // Try parse function definition
        if let Some(fname) = parse_fn_def(raw) {
            if let Some(mut c) = pending_cmd.take() {
                // Derive command name from fn name
                // By default the command name equals the fn name with '_' replaced by '-'
                let cmd_name = derive_cmd_name(&fname, &c.aliases);
                c.name = cmd_name;
                c.command_fn = Some(fname);
                root.subcommands.push(c);
                in_root = true;
            } else if in_root {
                // root function; no action unless it's specifically the root
            }
            i += 1;
            prev_blank = false;
            continue;
        }

        // Other non-empty lines
        prev_blank = false;
        i += 1;
    }

    // Validate: no dangling pending
    Ok(root)
}

fn derive_cmd_name(fname: &str, _aliases: &[String]) -> String {
    // Convention: replace underscores with hyphens for subcommand names.
    // Actually argc uses the fn name replacing '_' -> '-' for top-level, and splits by '_' for nested.
    // For now just hyphenate once.
    fname.replace('_', "-")
}

#[derive(Debug)]
pub struct Tag<'a> {
    pub name: &'a str,
    pub rest: &'a str,
}

fn parse_tag_line(line: &str) -> Option<Tag> {
    let s = line.trim_start();
    if !s.starts_with('#') { return None; }
    let s = &s[1..];
    let s = s.trim_start();
    if !s.starts_with('@') { return None; }
    let s = &s[1..];
    // split first whitespace
    let (tag, rest) = match s.find(|c: char| c.is_whitespace()) {
        Some(idx) => (&s[..idx], s[idx..].trim()),
        None => (s, ""),
    };
    Some(Tag { name: tag, rest })
}

fn parse_fn_def(raw: &str) -> Option<String> {
    let s = raw.trim_start();
    // Patterns:
    //   fname() {
    //   function fname {
    //   function fname() {
    if let Some(rest) = s.strip_prefix("function ") {
        let rest = rest.trim_start();
        let end = rest.find(|c: char| c == '(' || c.is_whitespace() || c == '{').unwrap_or(rest.len());
        let name = &rest[..end];
        if is_ident_fn(name) { return Some(name.to_string()); }
        return None;
    }
    // plain: fname()
    // Find '('
    if let Some(idx) = s.find('(') {
        let name = s[..idx].trim_end();
        if is_ident_fn(name) {
            let after = s[idx..].trim_start();
            if after.starts_with("()") { return Some(name.to_string()); }
        }
    }
    None
}

fn is_ident_fn(name: &str) -> bool {
    if name.is_empty() { return false; }
    // identifier chars: alnum, _, -, : etc. Bash allows many. Be permissive.
    for c in name.chars() {
        if c.is_alphanumeric() || c == '_' || c == '-' || c == ':' || c == '.' { continue; }
        return false;
    }
    true
}

fn apply_tag(root: &mut Command, pending: &mut Option<Command>, in_root: bool, tag: &Tag) -> Result<(), String> {
    let target = if in_root { root } else { pending.as_mut().expect("pending cmd missing") };
    match tag.name {
        "describe" => {
            target.describe = tag.rest.to_string();
        }
        "version" => {
            target.version = Some(tag.rest.to_string());
        }
        "author" => {
            target.author = Some(tag.rest.to_string());
        }
        "alias" => {
            let rest = tag.rest;
            for a in rest.split(|c: char| c == ',' || c.is_whitespace()) {
                let a = a.trim();
                if !a.is_empty() { target.aliases.push(a.to_string()); }
            }
        }
        "meta" => {
            parse_meta(target, tag.rest);
        }
        "flag" => {
            let fo = parse_flag_or_option(tag.rest, true)?;
            target.flag_options.push(fo);
        }
        "option" => {
            let fo = parse_flag_or_option(tag.rest, false)?;
            target.flag_options.push(fo);
        }
        "arg" => {
            let p = parse_positional(tag.rest)?;
            target.positionals.push(p);
        }
        "env" => {
            let e = parse_env(tag.rest)?;
            target.envs.push(e);
        }
        _ => {}
    }
    Ok(())
}

fn parse_meta(cmd: &mut Command, rest: &str) {
    let (name, args) = match rest.find(|c: char| c.is_whitespace()) {
        Some(idx) => (&rest[..idx], rest[idx..].trim()),
        None => (rest, ""),
    };
    match name {
        "combine-shorts" => cmd.meta_combine_shorts = true,
        "inherit-flag-options" => cmd.meta_inherit_flag_options = true,
        "default-subcommand" => cmd.meta_default_subcommand = true,
        "dotenv" => cmd.meta_dotenv = Some(args.to_string()),
        "require-tools" => {
            for t in args.split(|c: char| c == ',' || c.is_whitespace()) {
                let t = t.trim();
                if !t.is_empty() { cmd.meta_require_tools.push(t.to_string()); }
            }
        }
        "symbol" => {
            // symbol +toolchain[`_choice_fn`]
            // store raw
            cmd.meta_symbols.push((args.to_string(), String::new()));
        }
        "man-name" => cmd.meta_man_name = Some(args.to_string()),
        "man-section" => cmd.meta_man_section = Some(args.to_string()),
        "version" => cmd.version = Some(args.to_string()),
        "author" => cmd.author = Some(args.to_string()),
        _ => {}
    }
}

// Parse @flag and @option body.
pub fn parse_flag_or_option(s: &str, is_flag: bool) -> Result<FlagOption, String> {
    // We parse tokens separated by whitespace but carefully:
    //   [short] [long] [notations...] [$env] [describe...]
    // The "name" token is the one starting with -- or - or +
    // A "short" is like -x (len 2). Everything after name+notations+env is description.
    let mut fo = FlagOption::default();
    fo.flag = is_flag;
    let tokens = tokenize(s);

    let mut idx = 0usize;
    let mut name_tokens: Vec<String> = Vec::new();
    // Collect up to 2 leading name-like tokens (short, long)
    while idx < tokens.len() {
        let t = &tokens[idx];
        if is_name_token(t) {
            name_tokens.push(t.clone());
            idx += 1;
            if name_tokens.len() == 2 { break; }
            continue;
        }
        break;
    }
    if name_tokens.is_empty() {
        return Err(format!("flag/option missing name: {}", s));
    }
    // Classify: if both are short (single-dash len 2), the second is actually long single-dash? No, both short is rare.
    // Pattern: short comes first if length 2 (or 2 with + prefix), else long.
    // The "main" name is considered the longer one.
    // But also single-hyphen multi-char like `-fa` is a long single-hyphen form.
    assign_names(&mut fo, &name_tokens);

    // Process modifiers encoded in the name strings (like --foo*, --foo!, --foo+, --foo:, --foo=default)
    extract_modifiers(&mut fo);

    // Collect notations <...>
    while idx < tokens.len() {
        let t = &tokens[idx];
        if t.starts_with('<') && t.ends_with('>') && t.len() >= 2 {
            let inner = &t[1..t.len()-1];
            fo.notations.push(inner.to_string());
            idx += 1;
            continue;
        }
        break;
    }

    // $env binding
    if idx < tokens.len() && tokens[idx].starts_with('$') {
        let token = &tokens[idx];
        let envname = &token[1..];
        let envname = if envname == "$" {
            // $$ → derive from id
            auto_env_name(&fo.id)
        } else {
            envname.to_string()
        };
        fo.env = Some(envname);
        idx += 1;
    }

    // The remainder is describe
    if idx < tokens.len() {
        let rest = tokens[idx..].join(" ");
        fo.describe = rest;
    }

    finalize_flag_option(&mut fo, is_flag);
    Ok(fo)
}

fn assign_names(fo: &mut FlagOption, tokens: &[String]) {
    if tokens.len() == 1 {
        let t = &tokens[0];
        // If short (1 char after dash) put as short, else long
        let (prefix, body) = split_prefix(t);
        if prefix.len() == 1 && body.chars().count() == 1 {
            fo.short_name = t.clone();
        } else {
            fo.long_name = t.clone();
            if prefix.len() == 1 && body.chars().count() > 1 {
                // single-hyphen long like -fa
                fo.raw_name = t.clone();
            }
        }
    } else {
        // 2 tokens: first short, second long typically.
        let (p1, b1) = split_prefix(&tokens[0]);
        let (p2, b2) = split_prefix(&tokens[1]);
        let t1 = &tokens[0];
        let t2 = &tokens[1];
        if p1.len() == 1 && b1.chars().count() == 1 {
            fo.short_name = t1.clone();
            fo.long_name = t2.clone();
            if p2.len() == 1 && b2.chars().count() > 1 {
                fo.raw_name = t2.clone();
            }
        } else if p2.len() == 1 && b2.chars().count() == 1 {
            fo.short_name = t2.clone();
            fo.long_name = t1.clone();
            if p1.len() == 1 && b1.chars().count() > 1 {
                fo.raw_name = t1.clone();
            }
        } else {
            // Both look long-like; first is short-ish in order
            fo.short_name = t1.clone();
            fo.long_name = t2.clone();
        }
    }
    // Derive id
    let base = if !fo.long_name.is_empty() { &fo.long_name } else { &fo.short_name };
    fo.id = sanitize_id(base);
}

fn split_prefix(t: &str) -> (String, String) {
    let mut prefix = String::new();
    let chars: Vec<char> = t.chars().collect();
    let mut i = 0;
    while i < chars.len() && (chars[i] == '-' || chars[i] == '+') {
        prefix.push(chars[i]);
        i += 1;
    }
    let body: String = chars[i..].iter().collect();
    (prefix, body)
}

fn is_name_token(t: &str) -> bool {
    t.starts_with("--") || t.starts_with("-") || t.starts_with("+")
}

fn sanitize_id(name: &str) -> String {
    let (_, body) = split_prefix(name);
    // Strip modifiers
    let body = strip_trailing_modifiers(&body);
    let body = body.replace('-', "_");
    // Find end at one of the modifier suffixes we may have left
    body
}

fn strip_trailing_modifiers(body: &str) -> String {
    // Remove trailing *, +, !, =..., :..., [..], ~, <...> (notations) etc.
    // These should already have been split off earlier by extract_modifiers
    // But when used from sanitize_id (before full extract), keep it simple.
    let mut end = body.len();
    let bytes = body.as_bytes();
    // Find first modifier char
    for (i, ch) in body.char_indices() {
        if ch == '*' || ch == '+' || ch == '!' || ch == '=' || ch == ':' || ch == '[' || ch == '~' {
            end = i;
            break;
        }
    }
    let _ = bytes;
    body[..end].to_string()
}

fn extract_modifiers(fo: &mut FlagOption) {
    // We need to extract modifiers from long_name or short_name (whichever has the body after prefix)
    // The modifiers only exist on one (whichever was written with them).
    let modified = if has_any_modifier(&fo.long_name) {
        let s = fo.long_name.clone();
        let new = parse_name_with_modifiers(fo, &s);
        fo.long_name = new;
        true
    } else if has_any_modifier(&fo.short_name) {
        let s = fo.short_name.clone();
        let new = parse_name_with_modifiers(fo, &s);
        fo.short_name = new;
        true
    } else {
        false
    };
    let _ = modified;
    // Recompute id since the name may have been trimmed
    let base = if !fo.long_name.is_empty() { &fo.long_name } else { &fo.short_name };
    fo.id = sanitize_id(base);
}

fn has_any_modifier(name: &str) -> bool {
    name.contains('*') || name.contains('+') || name.contains('!') || name.contains('=') || name.contains(':') || name.contains('[') || name.contains('~')
}

fn parse_name_with_modifiers(fo: &mut FlagOption, name: &str) -> String {
    let (prefix, body) = split_prefix(name);
    // Find the split point where modifiers start.
    let mut end = body.len();
    for (i, ch) in body.char_indices() {
        if ch == '*' || ch == '+' || ch == '!' || ch == '=' || ch == ':' || ch == '[' || ch == '~' {
            end = i;
            break;
        }
    }
    let (base, rest) = body.split_at(end);
    let base_name = format!("{}{}", prefix, base);

    // Now parse `rest` for modifiers
    let mut chars = rest.chars().peekable();
    let mut rest_str = rest.to_string();
    while let Some(&c) = chars.peek() {
        match c {
            '*' => { fo.multiple_occurs = true; chars.next(); }
            '+' => { fo.multiple_occurs = true; fo.required = true; chars.next(); }
            '!' => { fo.required = true; chars.next(); }
            ',' => { fo.delimiter = Some(",".into()); chars.next(); }
            '~' => { fo.terminated = true; chars.next(); }
            '[' => {
                // choice
                // Find matching ]
                let idx = chars_clone_as_str(&chars).find(']');
                if let Some(end_i) = idx {
                    let inner: String = (&mut chars).take(end_i).collect();
                    // drop '[' first
                    // NOTE: we already peeked '['; take() above consumed it; adjust:
                    // Actually chars.take() returned elements including '['? Peek doesn't consume.
                    // Let me redo
                    let _ = inner; // discard mis-impl
                }
                // Proper handling below (overrides above)
                break;
            }
            '=' => {
                chars.next();
                let remaining: String = chars.collect();
                // default value
                let def = parse_default_value(&remaining);
                fo.default = Some(def);
                rest_str = String::new();
                break;
            }
            ':' => {
                chars.next();
                fo.assigned = true;
                // remaining may have more modifiers - but typically :[a|b]
                // Recurse
                let remaining: String = chars.collect();
                parse_modifier_suffix(fo, &remaining);
                rest_str = String::new();
                break;
            }
            _ => break,
        }
    }
    // Now handle '[' choice if present
    // Reconsume using string
    let post: String = rest_str;
    // re-scan
    let idx_bracket = post.find('[');
    let idx_eq_not_yet = post.find('=');
    let _ = (idx_bracket, idx_eq_not_yet);
    // We attempt a simpler approach: re-parse from `rest` directly with a state machine:
    parse_modifier_suffix(fo, rest);

    base_name
}

fn chars_clone_as_str(it: &std::iter::Peekable<std::str::Chars>) -> String {
    // not actually cloneable easily; placeholder
    it.clone().collect()
}

fn parse_modifier_suffix(fo: &mut FlagOption, rest: &str) {
    // Parse a modifier suffix like:
    //   * + ! , ~
    //   =value or =`fn`
    //   [a|b] [=a|b] [?fn] [`fn`] [?`fn`]
    //   : (assigned) optionally followed by the above
    let mut i = 0;
    let bytes: Vec<char> = rest.chars().collect();
    // Prefixed option detection: name ends with `-` followed by modifier — handled at name level
    if let Some(last) = rest.chars().last() {
        let _ = last;
    }
    while i < bytes.len() {
        let c = bytes[i];
        match c {
            '*' => { fo.multiple_occurs = true; i += 1; }
            '+' => { fo.multiple_occurs = true; fo.required = true; i += 1; }
            '!' => { fo.required = true; i += 1; }
            ',' => { fo.delimiter = Some(",".into()); i += 1; }
            '~' => { fo.terminated = true; i += 1; }
            ':' => { fo.assigned = true; i += 1; }
            '=' => {
                let rem: String = bytes[i+1..].iter().collect();
                fo.default = Some(parse_default_value(&rem));
                return;
            }
            '[' => {
                // find matching ]
                let rem: String = bytes[i..].iter().collect();
                if let Some(end_off) = rem.find(']') {
                    let inner = &rem[1..end_off];
                    parse_choice(fo, inner);
                    i += end_off + 1;
                } else {
                    return;
                }
            }
            _ => return,
        }
    }
}

fn parse_choice(fo: &mut FlagOption, inner: &str) {
    let mut check = true;
    let mut body = inner;
    if body.starts_with('?') { check = false; body = &body[1..]; }
    if body.starts_with('=') {
        // default from first choice
        body = &body[1..];
        let vals: Vec<String> = body.split('|').map(|s| s.to_string()).collect();
        if !vals.is_empty() {
            fo.default = Some(DefaultValue::Value(vals[0].clone()));
        }
        fo.choice = Some(ChoiceValue::Values(vals, check));
        return;
    }
    if body.starts_with('`') && body.ends_with('`') && body.len() >= 2 {
        let fn_name = &body[1..body.len()-1];
        fo.choice = Some(ChoiceValue::Fn(fn_name.to_string(), check));
        return;
    }
    let vals: Vec<String> = body.split('|').map(|s| s.to_string()).collect();
    fo.choice = Some(ChoiceValue::Values(vals, check));
}

fn parse_default_value(s: &str) -> DefaultValue {
    let s = s.trim();
    if s.starts_with('`') && s.ends_with('`') && s.len() >= 2 {
        DefaultValue::Fn(s[1..s.len()-1].to_string())
    } else {
        // Could be quoted string
        let v = strip_quotes(s);
        DefaultValue::Value(v)
    }
}

fn strip_quotes(s: &str) -> String {
    if s.len() >= 2 {
        let b = s.as_bytes();
        if (b[0] == b'"' && b[b.len()-1] == b'"') || (b[0] == b'\'' && b[b.len()-1] == b'\'') {
            return s[1..s.len()-1].to_string();
        }
    }
    s.to_string()
}

fn finalize_flag_option(fo: &mut FlagOption, is_flag: bool) {
    if is_flag {
        fo.num_args = (0, 0);
        fo.flag = true;
    } else {
        // Derive num_args from notations
        let min = if fo.required { 1 } else { 1 };
        let max = if fo.multiple_values || !fo.notations.is_empty() { 1 } else { 1 };
        let _ = (min, max);

        // Compute notation from id if empty
        if fo.notations.is_empty() {
            // Default notation: uppercase id
            let notation = fo.id.to_uppercase();
            fo.notations.push(notation);
            fo.num_args = (1, 1);
        } else {
            // Check last notation for modifiers
            let last_idx = fo.notations.len() - 1;
            let last = fo.notations[last_idx].clone();
            let mut min: u32 = fo.notations.len() as u32;
            let mut max: u32 = fo.notations.len() as u32;
            if last.ends_with('*') {
                fo.multiple_values = true;
                min = fo.notations.len() as u32 - 1;
                max = 1_000_000;
                fo.notations[last_idx] = last[..last.len()-1].to_string();
            } else if last.ends_with('+') {
                fo.multiple_values = true;
                min = fo.notations.len() as u32;
                max = 1_000_000;
                fo.notations[last_idx] = last[..last.len()-1].to_string();
            } else if last.ends_with('?') {
                min = fo.notations.len() as u32 - 1;
                max = fo.notations.len() as u32;
                fo.notations[last_idx] = last[..last.len()-1].to_string();
            }
            fo.num_args = (min, max);
        }
    }
}

fn auto_env_name(id: &str) -> String {
    id.to_uppercase()
}

pub fn parse_positional(s: &str) -> Result<Positional, String> {
    let mut p = Positional::default();
    let tokens = tokenize(s);
    let mut idx = 0;
    if idx >= tokens.len() { return Err("@arg missing name".into()); }
    // First token is name with modifiers
    let name_tok = &tokens[idx];
    idx += 1;
    parse_positional_name(&mut p, name_tok);
    // notations
    while idx < tokens.len() && tokens[idx].starts_with('<') && tokens[idx].ends_with('>') {
        let t = &tokens[idx];
        let inner = &t[1..t.len()-1];
        p.notation = inner.to_string();
        idx += 1;
        break;
    }
    // $env
    if idx < tokens.len() && tokens[idx].starts_with('$') {
        let t = &tokens[idx];
        let env = &t[1..];
        let env = if env == "$" { p.id.to_uppercase() } else { env.to_string() };
        p.env = Some(env);
        idx += 1;
    }
    // second attempt for notation (some put it after env)
    while idx < tokens.len() && tokens[idx].starts_with('<') && tokens[idx].ends_with('>') {
        let t = &tokens[idx];
        let inner = &t[1..t.len()-1];
        p.notation = inner.to_string();
        idx += 1;
    }
    // describe
    if idx < tokens.len() {
        p.describe = tokens[idx..].join(" ");
    }
    if p.notation.is_empty() {
        p.notation = p.id.to_uppercase();
    }
    Ok(p)
}

fn parse_positional_name(p: &mut Positional, tok: &str) {
    // tok like `val`, `val*`, `val+`, `val!`, `val=xyz`, `val[x|y|z]`, `val*[...]`, `vals~`, `val*,[...]`
    let bytes: Vec<char> = tok.chars().collect();
    let mut end = bytes.len();
    for (i, ch) in tok.char_indices() {
        if ch == '*' || ch == '+' || ch == '!' || ch == '=' || ch == '[' || ch == '~' || ch == ',' {
            end = i; break;
        }
    }
    let name = &tok[..end];
    p.id = name.to_string().replace('-', "_");
    let rest = &tok[end..];
    let mut i = 0;
    let rest_chars: Vec<char> = rest.chars().collect();
    while i < rest_chars.len() {
        match rest_chars[i] {
            '*' => { p.multiple = true; i += 1; }
            '+' => { p.multiple = true; p.required = true; i += 1; }
            '!' => { p.required = true; i += 1; }
            ',' => { p.delimiter = Some(",".into()); i += 1; }
            '~' => { p.terminated = true; p.multiple = true; i += 1; }
            '=' => {
                let rem: String = rest_chars[i+1..].iter().collect();
                p.default = Some(parse_default_value(&rem));
                return;
            }
            '[' => {
                let rem: String = rest_chars[i..].iter().collect();
                if let Some(end_off) = rem.find(']') {
                    let inner = &rem[1..end_off];
                    parse_choice_pos(p, inner);
                    i += end_off + 1;
                } else { return; }
            }
            _ => return,
        }
    }
}

fn parse_choice_pos(p: &mut Positional, inner: &str) {
    let mut check = true;
    let mut body = inner;
    if body.starts_with('?') { check = false; body = &body[1..]; }
    if body.starts_with('=') {
        body = &body[1..];
        let vals: Vec<String> = body.split('|').map(|s| s.to_string()).collect();
        if !vals.is_empty() { p.default = Some(DefaultValue::Value(vals[0].clone())); }
        p.choice = Some(ChoiceValue::Values(vals, check));
        return;
    }
    if body.starts_with('`') && body.ends_with('`') && body.len() >= 2 {
        p.choice = Some(ChoiceValue::Fn(body[1..body.len()-1].to_string(), check));
        return;
    }
    let vals: Vec<String> = body.split('|').map(|s| s.to_string()).collect();
    p.choice = Some(ChoiceValue::Values(vals, check));
}

pub fn parse_env(s: &str) -> Result<EnvParam, String> {
    let mut e = EnvParam::default();
    let tokens = tokenize(s);
    if tokens.is_empty() { return Err("@env missing name".into()); }
    let name_tok = &tokens[0];
    parse_env_name(&mut e, name_tok);
    if tokens.len() > 1 {
        e.describe = tokens[1..].join(" ");
    }
    Ok(e)
}

fn parse_env_name(e: &mut EnvParam, tok: &str) {
    let mut end = tok.len();
    for (i, ch) in tok.char_indices() {
        if ch == '*' || ch == '+' || ch == '!' || ch == '=' || ch == '[' {
            end = i; break;
        }
    }
    e.id = tok[..end].to_string();
    let rest = &tok[end..];
    let rest_chars: Vec<char> = rest.chars().collect();
    let mut i = 0;
    while i < rest_chars.len() {
        match rest_chars[i] {
            '*' => { i += 1; }
            '+' | '!' => { e.required = true; i += 1; }
            '=' => {
                let rem: String = rest_chars[i+1..].iter().collect();
                e.default = Some(parse_default_value(&rem));
                return;
            }
            '[' => {
                let rem: String = rest_chars[i..].iter().collect();
                if let Some(end_off) = rem.find(']') {
                    let inner = &rem[1..end_off];
                    let mut check = true;
                    let mut body = inner;
                    if body.starts_with('?') { check = false; body = &body[1..]; }
                    if body.starts_with('=') {
                        body = &body[1..];
                        let vals: Vec<String> = body.split('|').map(|s| s.to_string()).collect();
                        if !vals.is_empty() { e.default = Some(DefaultValue::Value(vals[0].clone())); }
                        e.choice = Some(ChoiceValue::Values(vals, check));
                    } else if body.starts_with('`') && body.ends_with('`') && body.len() >= 2 {
                        e.choice = Some(ChoiceValue::Fn(body[1..body.len()-1].to_string(), check));
                    } else {
                        let vals: Vec<String> = body.split('|').map(|s| s.to_string()).collect();
                        e.choice = Some(ChoiceValue::Values(vals, check));
                    }
                    i += end_off + 1;
                } else { return; }
            }
            _ => return,
        }
    }
}

/// Tokenize a line into whitespace-separated tokens, respecting backticks and <> and [].
pub fn tokenize(s: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut cur = String::new();
    let mut depth = 0i32; // for [ ] and < >
    let mut in_tick = false;
    let mut in_single = false;
    let mut in_double = false;
    for c in s.chars() {
        if in_tick {
            cur.push(c);
            if c == '`' { in_tick = false; }
            continue;
        }
        if in_single {
            cur.push(c);
            if c == '\'' { in_single = false; }
            continue;
        }
        if in_double {
            cur.push(c);
            if c == '"' { in_double = false; }
            continue;
        }
        match c {
            '`' => { cur.push(c); in_tick = true; }
            '\'' => { cur.push(c); in_single = true; }
            '"' => { cur.push(c); in_double = true; }
            '[' | '<' => { depth += 1; cur.push(c); }
            ']' | '>' => { depth -= 1; cur.push(c); }
            ch if ch.is_whitespace() && depth <= 0 => {
                if !cur.is_empty() { out.push(std::mem::take(&mut cur)); }
            }
            _ => cur.push(c),
        }
    }
    if !cur.is_empty() { out.push(cur); }
    out
}
