    for (i, n) in notations.iter().enumerate() {
        if i > 0 { out.push(' '); }
        out.push('<');
        out.push_str(n);
        out.push('>');
    }
    if f.multiple_values || f.multiple_occurs {
        out.push_str("...");
    }
    if f.terminated {
        // e.g., <OXA~>
        // replace last <X> with <X~>
        // Recompute
        let mut out2 = String::new();
        for (i, n) in notations.iter().enumerate() {
            if i > 0 { out2.push(' '); }
            out2.push('<');
            out2.push_str(n);
            out2.push('~');
            out2.push('>');
        }
        return out2;
    }
    out
