pub fn dispatch(root: &Command, args: &[String], path: &mut Vec<String>, _file: &str) -> Result<String, String> {
    // args here includes raw CLI args after the script name.
    // We walk subcommands.
    let mut cur = root.clone();
    let mut i = 0;
    let mut full_args: Vec<String> = vec![root.name.clone()];
    full_args.extend_from_slice(args);

    // Try dispatch subcommand
    let mut cmd_path: Vec<String> = vec![root.name.clone()];
    // If root has no subcommands, parse root directly
    // Process flags at root level first
    // If args[i] is a subcommand name, descend
    // For argc, you can also have root fn.

    // For simplicity, check first non-flag arg
    let mut pre_flags: Vec<String> = vec![];
    let mut subcommand_idx: Option<usize> = None;
    {
        let mut j = 0;
        while j < args.len() {
            let a = &args[j];
            if a == "--" { break; }
            if a.starts_with('-') || a.starts_with('+') {
                // flag-ish - skip value if looks like option
                // For dispatch we just pass
                pre_flags.push(a.clone());
                j += 1;
                // Also skip potential value
                if !a.starts_with("--") {
                    // short
                }
                // For sub-detection just continue
                continue;
            } else if cur.find_subcommand(a).is_some() {
                subcommand_idx = Some(j);
                break;
            } else {
                break;
            }
        }
    }

    let _ = pre_flags;

    // If subcommand at position j, descend
    if let Some(j) = subcommand_idx {
        // Handle root-level flags before the subcommand (like --help, --version)
        for k in 0..j {
            let a = &args[k];
            if a == "-h" || a == "--help" {
                // Print help for current cur
                path.clear();
                path.push(root.name.clone());
                let mut out = help::render_help(&cur, &path);
                // Root always adds --version if cur has version or is root
                if cur.version.is_some() {
                    // already handled in render_help via default_version_flag? we don't add it automatically.
                }
                return Ok(help_as_bash(&out));
            }
            if a == "-V" || a == "--version" {
                if let Some(v) = &cur.version {
                    return Ok(version_as_bash(&cur.name, v));
                }
            }
        }
        let sub_name = &args[j];
        let sub = cur.find_subcommand(sub_name).unwrap().clone();
        cmd_path.push(sub.name.clone());
        // Remaining args after subcommand
        let rest: Vec<String> = args[j+1..].to_vec();
        return dispatch_cmd(&sub, &rest, &cmd_path, &full_args);
    }

    // Or "help" subcommand
    // Handle root-level flags if no subcommand
    // If root has subcommands but none given, show help (error)
    if !cur.subcommands.is_empty() {
        // Check if user supplied -h/--help or -V/--version
        for a in args {
            if a == "-h" || a == "--help" {
                let out = help::render_help(&cur, &cmd_path);
                return Ok(help_as_bash(&out));
            }
            if a == "-V" || a == "--version" {
                let v = cur.version.clone().unwrap_or_else(|| "0.0.0".to_string());
                return Ok(version_as_bash(&cur.name, &v));
            }
        }
        // default_subcommand
        for sc in &cur.subcommands {
            if sc.meta_default_subcommand {
                let sub = sc.clone();
                cmd_path.push(sub.name.clone());
                return dispatch_cmd(&sub, args, &cmd_path, &full_args);
            }
        }
        // Otherwise show help
        let out = help::render_help(&cur, &cmd_path);
        return Ok(help_as_bash(&out));
    }

    // No subcommands: parse root args
    dispatch_cmd(&cur, args, &cmd_path, &full_args)
}

fn dispatch_cmd(cmd: &Command, args: &[String], path: &[String], full_args: &[String]) -> Result<String, String> {
    // Check for -h/--help, -V/--version
    for a in args {
        if a == "-h" || a == "--help" {
            let out = help::render_help(cmd, path);
            return Ok(help_as_bash(&out));
        }
        if a == "-V" || a == "--version" {
            let v = cmd.version.clone().unwrap_or_else(|| "0.0.0".to_string());
            return Ok(version_as_bash(&cmd.name, &v));
        }
    }

    // Parse args
    let parsed = parse_cli_args(cmd, args)?;

    // Build bash output
    let mut bash = String::new();
    // Variables
    let mut var_decls: Vec<String> = Vec::new();

    // flag/option values
    for fo in &cmd.flag_options {
        if fo.flag {
            // count occurrences
            let count = parsed.flag_count.get(&fo.id).copied().unwrap_or(0);
            if count > 0 {
                if fo.multiple_occurs {
                    var_decls.push(format!("argc_{}={}", fo.id, count));
                } else {
                    var_decls.push(format!("argc_{}=1", fo.id));
                }
            }
        } else {
            // option values
            if let Some(vals) = parsed.option_values.get(&fo.id) {
                if fo.multiple_values || fo.multiple_occurs {
                    let inner = vals.iter().map(|v| bash_escape(v)).collect::<Vec<_>>().join(" ");
                    var_decls.push(format!("argc_{}=( {} )", fo.id, inner));
                } else if vals.len() == 1 {
                    var_decls.push(format!("argc_{}={}", fo.id, bash_escape(&vals[0])));
                }
            } else if let Some(def) = &fo.default {
                match def {
                    DefaultValue::Value(v) => {
                        var_decls.push(format!("argc_{}={}", fo.id, bash_escape(v)));
                    }
                    DefaultValue::Fn(_fn) => {
                        // run fn later? For now, leave as unset
                        // Actually argc generates: argc_name=$(_fn)
                        var_decls.push(format!("argc_{}=$(_argc_take_fn_value_{})", fo.id, fo.id));
                    }
                }
            }
        }
    }

    // positionals
    let pos_values: Vec<Vec<String>> = parsed.positional_values.clone();
    for (i, p) in cmd.positionals.iter().enumerate() {
        let vals = pos_values.get(i).cloned().unwrap_or_default();
        if vals.is_empty() {
            if let Some(def) = &p.default {
                match def {
                    DefaultValue::Value(v) => {
                        var_decls.push(format!("argc_{}={}", p.id, bash_escape(v)));
                    }
                    _ => {}
                }
            }
            continue;
        }
        if p.multiple {
            let inner = vals.iter().map(|v| bash_escape(v)).collect::<Vec<_>>().join(" ");
            var_decls.push(format!("argc_{}=( {} )", p.id, inner));
        } else {
            var_decls.push(format!("argc_{}={}", p.id, bash_escape(&vals[0])));
        }
    }

    // argc__args
    let full_args_escaped: Vec<String> = full_args.iter().map(|a| bash_escape(a)).collect();
    var_decls.push(format!("argc__args=( {} )", full_args_escaped.join(" ")));
    if let Some(fn_name) = &cmd.command_fn {
        var_decls.push(format!("argc__fn={}", fn_name));
    }
    let all_positionals: Vec<String> = pos_values.iter().flatten().cloned().collect();
    let all_positionals_esc: Vec<String> = all_positionals.iter().map(|a| bash_escape(a)).collect();
    var_decls.push(format!("argc__positionals=( {} )", all_positionals_esc.join(" ")));

    // Build the encoded line
    let joined = var_decls.iter().map(|s| format!("{};", s)).collect::<String>();
    let encoded = base64::encode(joined.as_bytes());
    bash.push_str(&format!("export ARGC_VARS={}\n", encoded));
    for v in &var_decls {
        bash.push_str(v);
        bash.push('\n');
    }
    if let Some(fn_name) = &cmd.command_fn {
        let suffix = all_positionals_esc.join(" ");
        bash.push_str(&format!("{} {}", fn_name, suffix));
    }
    // trim trailing newline
    Ok(bash.trim_end().to_string())
}

fn help_as_bash(body: &str) -> String {
    let mut out = String::new();
    out.push_str("command cat >&2 <<-'EOF' \n");
    out.push_str(body);
    out.push('\n');
    out.push_str("EOF\n");
    out.push_str("exit 0");
    out
}

fn version_as_bash(name: &str, v: &str) -> String {
    let mut out = String::new();
    out.push_str("command cat >&2 <<-'EOF' \n");
    out.push_str(&format!("{} {}", name, v));
    out.push('\n');
    out.push_str("EOF\n");
    out.push_str("exit 0");
    out
}

use std::collections::HashMap;
struct ParsedCli {
    flag_count: HashMap<String, usize>,
    option_values: HashMap<String, Vec<String>>,
    positional_values: Vec<Vec<String>>,
}

fn parse_cli_args(cmd: &Command, args: &[String]) -> Result<ParsedCli, String> {
    let mut flag_count: HashMap<String, usize> = HashMap::new();
    let mut option_values: HashMap<String, Vec<String>> = HashMap::new();
    let mut positional_raw: Vec<String> = Vec::new();

    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if a == "--" {
            i += 1;
            while i < args.len() {
                positional_raw.push(args[i].clone());
                i += 1;
            }
            break;
        }
        // --foo=value
        if a.starts_with("--") || a.starts_with("-") || a.starts_with("+") {
            let (name, eq_value) = match a.find('=') {
                Some(idx) if a.starts_with("--") => (a[..idx].to_string(), Some(a[idx+1..].to_string())),
                _ => (a.clone(), None),
            };
            if let Some(f) = cmd.find_flag_option(&name) {
                let fo = f.clone();
                if fo.flag {
                    *flag_count.entry(fo.id.clone()).or_insert(0) += 1;
                    i += 1;
                    continue;
                }
                // Option: collect values
                let num_vals = if fo.num_args.0 >= 1 { fo.num_args.0 as usize } else { 1 };
                let max_vals = fo.num_args.1 as usize;
                let mut vals: Vec<String> = Vec::new();
                if let Some(v) = eq_value {
                    // split by delimiter
                    if let Some(d) = &fo.delimiter {
                        for part in v.split(d.as_str()) {
                            vals.push(part.to_string());
                        }
                    } else {
                        vals.push(v);
                    }
                    i += 1;
                } else {
                    i += 1;
                    let mut taken = 0;
                    while i < args.len() && taken < max_vals {
                        let v = &args[i];
                        if v.starts_with('-') && taken >= num_vals { break; }
                        if let Some(d) = &fo.delimiter {
                            for part in v.split(d.as_str()) {
                                vals.push(part.to_string());
                            }
                        } else {
                            vals.push(v.clone());
                        }
                        i += 1;
                        taken += 1;
                        if !fo.multiple_values && taken >= num_vals { break; }
                    }
                }
                if let Some(c) = &fo.choice {
                    if let ChoiceValue::Values(cvals, true) = c {
                        for v in &vals {
                            if !cvals.contains(v) {
                                return Err(format!("error: '{}' isn't a valid value for '{}'", v, fo.long_name));
                            }
                        }
                    }
                }
                option_values.entry(fo.id.clone()).or_insert_with(Vec::new).extend(vals);
                continue;
            } else {
                // Unknown option
                return Err(format!("error: unexpected argument `{}` found", a));
            }
        }
        // Positional
        positional_raw.push(a.clone());
        i += 1;
    }

    // Check required flags/options
    let mut missing: Vec<String> = Vec::new();
    for fo in &cmd.flag_options {
        if fo.flag { continue; }
        if fo.required {
            if !option_values.contains_key(&fo.id) {
                let name = if !fo.long_name.is_empty() { &fo.long_name } else { &fo.short_name };
                let notation = if !fo.notations.is_empty() { fo.notations[0].clone() } else { fo.id.to_uppercase() };
                let suffix = if fo.multiple_values || fo.multiple_occurs { "..." } else { "" };
                missing.push(format!("{} <{}>{}", name, notation, suffix));
            }
        }
    }

    // distribute positionals
    let positional_values = distribute_positionals(&cmd.positionals, &positional_raw, &mut missing)?;

    if !missing.is_empty() {
        let mut msg = String::from("error: the following required arguments were not provided:");
        for m in &missing {
            msg.push_str("\n  ");
            msg.push_str(m);
        }
        return Err(msg);
    }

    Ok(ParsedCli { flag_count, option_values, positional_values })
}

fn distribute_positionals(defs: &[Positional], raw: &[String], missing: &mut Vec<String>) -> Result<Vec<Vec<String>>, String> {
    // Allocate positionals to arg definitions (simple greedy).
    let mut out: Vec<Vec<String>> = vec![Vec::new(); defs.len()];
    if defs.is_empty() {
        if !raw.is_empty() {
            return Err(format!("error: unexpected argument `{}` found", raw[0]));
        }
        return Ok(out);
    }
    // Count how many multi ones
    let mut remain = raw.len();
    // Compute minimum needed per slot
    let mut min_needed: Vec<usize> = defs.iter().map(|p| if p.required { 1 } else { 0 }).collect();
    // Multi-required slot uses at least 1
    // Distribute: for each slot, take 1 if single; if multi, take remainder minus required for rest
    let mut idx = 0usize;
    for (i, p) in defs.iter().enumerate() {
        if !p.multiple {
            if idx < raw.len() {
                out[i].push(raw[idx].clone());
                idx += 1;
                remain = raw.len().saturating_sub(idx);
            } else if p.required {
                let notation = if !p.notation.is_empty() { p.notation.clone() } else { p.id.to_uppercase() };
                missing.push(format!("<{}>", notation));
            }
        } else {
            // Multi: grab remaining except min for rest
            let mut rest_required: usize = 0;
            for j in (i+1)..defs.len() {
                if defs[j].required { rest_required += 1; }
            }
            let take = remain.saturating_sub(rest_required);
            let end = idx + take;
            for k in idx..end {
                out[i].push(raw[k].clone());
            }
            if p.required && out[i].is_empty() {
                let notation = if !p.notation.is_empty() { p.notation.clone() } else { p.id.to_uppercase() };
                missing.push(format!("<{}>...", notation));
            }
            idx = end;
            remain = raw.len().saturating_sub(idx);
        }
    }
    if idx < raw.len() {
        return Err(format!("error: unexpected argument `{}` found", raw[idx]));
    }
    let _ = min_needed;
    Ok(out)
}

fn bash_escape(s: &str) -> String {
    if s.is_empty() { return "''".to_string(); }
    if s.chars().all(|c| c.is_alphanumeric() || "@%+=:,./_-".contains(c)) {
        return s.to_string();
    }
    let mut out = String::from("'");
    for c in s.chars() {
        if c == '\'' {
            out.push_str("'\\''");
        } else {
            out.push(c);
        }
    }
    out.push('\'');
    out
}
