fn dispatch_cmd(cmd: &Command, args: &[String], path: &[String], full_args: &[String]) -> Result<String, String> {
    // Check for -h/--help, -V/--version
    for a in args {
        if a == "-h" || a == "--help" {
            let out = help::render_help(cmd, path);
            return Ok(help_as_bash(&out));
        }
        if a == "-V" || a == "--version" {
            let v = cmd.version.clone().unwrap_or_else(|| "0.0.0".to_string());
            return Ok(version_as_bash(&cmd.name, &v));
        }
    }

    // Parse args
    let parsed = parse_cli_args(cmd, args)?;

    // Build bash output
    let mut bash = String::new();
    // Variables
    let mut var_decls: Vec<String> = Vec::new();

    // flag/option values
    for fo in &cmd.flag_options {
        if fo.flag {
            // count occurrences
            let count = parsed.flag_count.get(&fo.id).copied().unwrap_or(0);
            if count > 0 {
                if fo.multiple_occurs {
                    var_decls.push(format!("argc_{}={}", fo.id, count));
                } else {
                    var_decls.push(format!("argc_{}=1", fo.id));
                }
            }
        } else {
            // option values
            if let Some(vals) = parsed.option_values.get(&fo.id) {
                if fo.multiple_values || fo.multiple_occurs {
                    let inner = vals.iter().map(|v| bash_escape(v)).collect::<Vec<_>>().join(" ");
                    var_decls.push(format!("argc_{}=( {} )", fo.id, inner));
                } else if vals.len() == 1 {
                    var_decls.push(format!("argc_{}={}", fo.id, bash_escape(&vals[0])));
                }
            } else if let Some(def) = &fo.default {
                match def {
                    DefaultValue::Value(v) => {
                        var_decls.push(format!("argc_{}={}", fo.id, bash_escape(v)));
                    }
                    DefaultValue::Fn(_fn) => {
                        // run fn later? For now, leave as unset
                        // Actually argc generates: argc_name=$(_fn)
                        var_decls.push(format!("argc_{}=$(_argc_take_fn_value_{})", fo.id, fo.id));
                    }
                }
            }
        }
    }

    // positionals
    let pos_values: Vec<Vec<String>> = parsed.positional_values.clone();
    for (i, p) in cmd.positionals.iter().enumerate() {
        let vals = pos_values.get(i).cloned().unwrap_or_default();
        if vals.is_empty() {
            if let Some(def) = &p.default {
                match def {
                    DefaultValue::Value(v) => {
                        var_decls.push(format!("argc_{}={}", p.id, bash_escape(v)));
                    }
                    _ => {}
                }
            }
            continue;
        }
        if p.multiple {
            let inner = vals.iter().map(|v| bash_escape(v)).collect::<Vec<_>>().join(" ");
            var_decls.push(format!("argc_{}=( {} )", p.id, inner));
        } else {
            var_decls.push(format!("argc_{}={}", p.id, bash_escape(&vals[0])));
        }
    }

    // argc__args
    let full_args_escaped: Vec<String> = full_args.iter().map(|a| bash_escape(a)).collect();
    var_decls.push(format!("argc__args=( {} )", full_args_escaped.join(" ")));
    if let Some(fn_name) = &cmd.command_fn {
        var_decls.push(format!("argc__fn={}", fn_name));
    }
    let all_positionals: Vec<String> = pos_values.iter().flatten().cloned().collect();
    let all_positionals_esc: Vec<String> = all_positionals.iter().map(|a| bash_escape(a)).collect();
    var_decls.push(format!("argc__positionals=( {} )", all_positionals_esc.join(" ")));

    // Build the encoded line
    let joined = var_decls.iter().map(|s| format!("{};", s)).collect::<String>();
    let encoded = base64::encode(joined.as_bytes());
    bash.push_str(&format!("export ARGC_VARS={}\n", encoded));
    for v in &var_decls {
        bash.push_str(v);
        bash.push('\n');
    }
    if let Some(fn_name) = &cmd.command_fn {
        let suffix = all_positionals_esc.join(" ");
        bash.push_str(&format!("{} {}", fn_name, suffix));
    }
    // trim trailing newline
    Ok(bash.trim_end().to_string())
}

