use std::collections::HashMap;
struct ParsedCli {
    flag_count: HashMap<String, usize>,
    option_values: HashMap<String, Vec<String>>,
    positional_values: Vec<Vec<String>>,
}

fn parse_cli_args(cmd: &Command, args: &[String]) -> Result<ParsedCli, String> {
    let mut flag_count: HashMap<String, usize> = HashMap::new();
    let mut option_values: HashMap<String, Vec<String>> = HashMap::new();
    let mut positional_raw: Vec<String> = Vec::new();

    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if a == "--" {
            i += 1;
            while i < args.len() {
                positional_raw.push(args[i].clone());
                i += 1;
            }
            break;
        }
        // --foo=value
        if a.starts_with("--") || a.starts_with("-") || a.starts_with("+") {
            let (name, eq_value) = match a.find('=') {
                Some(idx) if a.starts_with("--") => (a[..idx].to_string(), Some(a[idx+1..].to_string())),
                _ => (a.clone(), None),
            };
            if let Some(f) = cmd.find_flag_option(&name) {
                let fo = f.clone();
                if fo.flag {
                    *flag_count.entry(fo.id.clone()).or_insert(0) += 1;
                    i += 1;
                    continue;
                }
                // Option: collect values
                let num_vals = if fo.num_args.0 >= 1 { fo.num_args.0 as usize } else { 1 };
                let max_vals = fo.num_args.1 as usize;
                let mut vals: Vec<String> = Vec::new();
                if let Some(v) = eq_value {
                    // split by delimiter
                    if let Some(d) = &fo.delimiter {
                        for part in v.split(d.as_str()) {
                            vals.push(part.to_string());
                        }
                    } else {
                        vals.push(v);
                    }
                    i += 1;
                } else {
                    i += 1;
                    let mut taken = 0;
                    while i < args.len() && taken < max_vals {
                        let v = &args[i];
                        if v.starts_with('-') && taken >= num_vals { break; }
                        if let Some(d) = &fo.delimiter {
                            for part in v.split(d.as_str()) {
                                vals.push(part.to_string());
                            }
                        } else {
                            vals.push(v.clone());
                        }
                        i += 1;
                        taken += 1;
                        if !fo.multiple_values && taken >= num_vals { break; }
                    }
                }
                if let Some(c) = &fo.choice {
                    if let ChoiceValue::Values(cvals, true) = c {
                        for v in &vals {
                            if !cvals.contains(v) {
                                return Err(format!("error: '{}' isn't a valid value for '{}'", v, fo.long_name));
                            }
                        }
                    }
                }
                option_values.entry(fo.id.clone()).or_insert_with(Vec::new).extend(vals);
                continue;
            } else {
                // Unknown option
                return Err(format!("error: unexpected argument `{}` found", a));
            }
        }
        // Positional
        positional_raw.push(a.clone());
        i += 1;
    }

    // Check required flags/options
    let mut missing: Vec<String> = Vec::new();
    for fo in &cmd.flag_options {
        if fo.flag { continue; }
        if fo.required {
            if !option_values.contains_key(&fo.id) {
                let name = if !fo.long_name.is_empty() { &fo.long_name } else { &fo.short_name };
                let notation = if !fo.notations.is_empty() { fo.notations[0].clone() } else { fo.id.to_uppercase() };
                let suffix = if fo.multiple_values || fo.multiple_occurs { "..." } else { "" };
                missing.push(format!("{} <{}>{}", name, notation, suffix));
            }
        }
    }

    // distribute positionals
    let positional_values = distribute_positionals(&cmd.positionals, &positional_raw, &mut missing)?;

    if !missing.is_empty() {
        let mut msg = String::from("error: the following required arguments were not provided:");
        for m in &missing {
            msg.push_str("\n  ");
            msg.push_str(m);
        }
        return Err(msg);
    }

    Ok(ParsedCli { flag_count, option_values, positional_values })
}

fn distribute_positionals(defs: &[Positional], raw: &[String], missing: &mut Vec<String>) -> Result<Vec<Vec<String>>, String> {
    // Allocate positionals to arg definitions (simple greedy).
    let mut out: Vec<Vec<String>> = vec![Vec::new(); defs.len()];
    if defs.is_empty() {
        if !raw.is_empty() {
            return Err(format!("error: unexpected argument `{}` found", raw[0]));
        }
        return Ok(out);
    }
    // Count how many multi ones
    let mut remain = raw.len();
    // Compute minimum needed per slot
    let mut min_needed: Vec<usize> = defs.iter().map(|p| if p.required { 1 } else { 0 }).collect();
    // Multi-required slot uses at least 1
    // Distribute: for each slot, take 1 if single; if multi, take remainder minus required for rest
    let mut idx = 0usize;
    for (i, p) in defs.iter().enumerate() {
        if !p.multiple {
            if idx < raw.len() {
                out[i].push(raw[idx].clone());
                idx += 1;
                remain = raw.len().saturating_sub(idx);
            } else if p.required {
                let notation = if !p.notation.is_empty() { p.notation.clone() } else { p.id.to_uppercase() };
                missing.push(format!("<{}>", notation));
            }
        } else {
            // Multi: grab remaining except min for rest
            let mut rest_required: usize = 0;
            for j in (i+1)..defs.len() {
                if defs[j].required { rest_required += 1; }
            }
            let take = remain.saturating_sub(rest_required);
            let end = idx + take;
            for k in idx..end {
                out[i].push(raw[k].clone());
            }
            if p.required && out[i].is_empty() {
                let notation = if !p.notation.is_empty() { p.notation.clone() } else { p.id.to_uppercase() };
                missing.push(format!("<{}>...", notation));
            }
            idx = end;
            remain = raw.len().saturating_sub(idx);
        }
    }
    if idx < raw.len() {
        return Err(format!("error: unexpected argument `{}` found", raw[idx]));
    }
    let _ = min_needed;
    Ok(out)
}

fn bash_escape(s: &str) -> String {
    if s.is_empty() { return "''".to_string(); }
    if s.chars().all(|c| c.is_alphanumeric() || "@%+=:,./_-".contains(c)) {
        return s.to_string();
    }
    let mut out = String::from("'");
    for c in s.chars() {
        if c == '\'' {
            out.push_str("'\\''");
        } else {
            out.push(c);
        }
    }
    out.push('\'');
    out
}
