    out.push_str(&indent_str(indent + 2)); out.push_str("\"describe\": "); push_json_str(out, &p.describe); out.push_str(",\n");
    out.push_str(&indent_str(indent + 2)); out.push_str("\"notation\": "); push_json_str(out, &p.notation); out.push_str(",\n");
    out.push_str(&indent_str(indent + 2)); out.push_str("\"required\": "); out.push_str(if p.required { "true" } else { "false" }); out.push_str(",\n");
    out.push_str(&indent_str(indent + 2)); out.push_str("\"multiple\": "); out.push_str(if p.multiple { "true" } else { "false" }); out.push_str(",\n");
    out.push_str(&indent_str(indent + 2)); out.push_str("\"delimiter\": ");
