    out.push_str(",\n");
    out.push_str(&indent_str(indent + 2)); out.push_str("\"terminated\": "); out.push_str(if p.terminated { "true" } else { "false" }); out.push_str(",\n");
    out.push_str(&indent_str(indent + 2)); out.push_str("\"default\": ");
    render_default(out, &p.default, indent + 2);
    out.push_str(",\n");
    out.push_str(&indent_str(indent + 2)); out.push_str("\"choice\": ");
    render_choice(out, &p.choice, indent + 2);
    out.push_str(",\n");
    out.push_str(&indent_str(indent + 2)); out.push_str("\"env\": ");
    match &p.env { Some(e) => push_json_str(out, e), None => out.push_str("null") }
    out.push('\n');
    out.push_str(&pad); out.push('}');
