    out.push_str(&indent_str(indent + 2)); out.push_str("\"delimiter\": ");
    match &p.delimiter { Some(d) => push_json_str(out, d), None => out.push_str("null") }
    out.push_str(",\n");
    out.push_str(&indent_str(indent + 2)); out.push_str("\"terminated\": "); out.push_str(if p.terminated { "true" } else { "false" }); out.push_str(",\n");
