fn render_env(out: &mut String, e: &EnvParam, indent: usize) {
    let pad = indent_str(indent);
    out.push_str(&pad);
    out.push_str("{\n");
    out.push_str(&indent_str(indent + 2)); out.push_str("\"id\": "); push_json_str(out, &e.id); out.push_str(",\n");
    out.push_str(&indent_str(indent + 2)); out.push_str("\"describe\": "); push_json_str(out, &e.describe); out.push_str(",\n");
    out.push_str(&indent_str(indent + 2)); out.push_str("\"required\": "); out.push_str(if e.required { "true" } else { "false" }); out.push_str(",\n");
    out.push_str(&indent_str(indent + 2)); out.push_str("\"default\": ");
    render_default(out, &e.default, indent + 2);
    out.push_str(",\n");
    out.push_str(&indent_str(indent + 2)); out.push_str("\"choice\": ");
    render_choice(out, &e.choice, indent + 2);
    out.push('\n');
    out.push_str(&pad); out.push('}');
}

fn render_default(out: &mut String, d: &Option<DefaultValue>, _indent: usize) {
    match d {
        None => out.push_str("null"),
        Some(DefaultValue::Value(v)) => push_json_str(out, v),
        Some(DefaultValue::Fn(f)) => push_json_str(out, &format!("`{}`", f)),
    }
}

fn render_choice(out: &mut String, c: &Option<ChoiceValue>, indent: usize) {
    match c {
        None => out.push_str("null"),
        Some(ChoiceValue::Values(vals, _)) => {
            out.push_str("[\n");
            for (i, v) in vals.iter().enumerate() {
                out.push_str(&indent_str(indent + 2));
                push_json_str(out, v);
                if i != vals.len()-1 { out.push(','); }
                out.push('\n');
            }
            out.push_str(&indent_str(indent));
            out.push(']');
        }
        Some(ChoiceValue::Fn(f, _)) => push_json_str(out, &format!("`{}`", f)),
    }
}

fn indent_str(n: usize) -> String { " ".repeat(n) }

fn push_json_str(out: &mut String, s: &str) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            _ => out.push(c),
        }
    }
    out.push('"');
}
