use crate::parser;
use std::fs;

pub fn compgen(shell: &str, file: &str, args: &[String]) -> Result<u8, String> {
    let _ = shell;
    let content = fs::read_to_string(file).map_err(|e| format!("Cannot read {}: {}", file, e))?;
    let root = parser::parse_script(file, &content)?;
    // args[0] is the base name (like `demo`), rest are current words.
    // Last arg is the partial we're completing.
    if args.is_empty() { return Ok(0); }
    let words: Vec<String> = args[1..].to_vec();
    let last = words.last().cloned().unwrap_or_default();
    // Walk subcommands
    let mut cur = &root;
    let mut i = 0;
    while i < words.len().saturating_sub(1) {
        let w = &words[i];
        if let Some(sub) = cur.find_subcommand(w) {
            cur = sub;
        }
        i += 1;
    }
    let mut out: Vec<(String, String)> = Vec::new();
    if last.is_empty() || last.starts_with('-') {
        // Flags/options
        for f in &cur.flag_options {
            if !f.long_name.is_empty() {
                if last.is_empty() || f.long_name.starts_with(&last) {
                    out.push((f.long_name.clone(), f.describe.clone()));
                }
            }
            if !f.short_name.is_empty() && !last.starts_with("--") {
                if last.is_empty() || f.short_name.starts_with(&last) {
                    out.push((f.short_name.clone(), f.describe.clone()));
                }
            }
        }
        // help/version
        if last.is_empty() || "--help".starts_with(&last) {
            out.push(("--help".into(), "Print help".into()));
        }
        if !last.starts_with("--") && (last.is_empty() || "-h".starts_with(&last)) {
            out.push(("-h".into(), "Print help".into()));
        }
        if last.is_empty() || "--version".starts_with(&last) {
            out.push(("--version".into(), "Print version".into()));
        }
        if !last.starts_with("--") && (last.is_empty() || "-V".starts_with(&last)) {
            out.push(("-V".into(), "Print version".into()));
        }
    } else {
        // Subcommands
        for sc in &cur.subcommands {
            if sc.name.starts_with(&last) {
                out.push((sc.name.clone(), sc.describe.clone()));
            }
        }
        if "help".starts_with(&last) {
            out.push(("help".into(), "Show help for a command".into()));
        }
    }
    for (n, d) in out {
        if d.is_empty() { println!("{} ", n); } else { println!("{} ({})", n, d); }
    }
    Ok(0)
}
