use crate::command::*;

pub struct HelpContext {
    pub is_root: bool,
    pub has_version: bool, // root always has implicit version
}

pub fn render_help(cmd: &Command, path: &[String], is_root: bool) -> String {
    let mut out = String::new();
    // Header (first line)
    let head = cmd.describe.clone();
    if !head.is_empty() {
        out.push_str(&head);
        out.push_str("\n\n");
    }

    let flag_opts = get_displayed_flag_options(cmd, is_root);
    let has_user_options = !cmd.flag_options.is_empty();
    let show_options_section = has_user_options || cmd.subcommands.is_empty();

    // USAGE
    out.push_str(&usage_line(cmd, path, show_options_section));
    out.push('\n');

    // ARGS
    let positional_visible: Vec<&Positional> = cmd.positionals.iter().collect();
    if !positional_visible.is_empty() {
        out.push_str("\nARGS:\n");
        render_positional_table(&mut out, &positional_visible);
    }

    // COMMANDS
    if !cmd.subcommands.is_empty() {
        out.push_str("\nCOMMANDS:\n");
        render_subcommands_table(&mut out, cmd);
    }

    // OPTIONS
    if show_options_section {
        out.push_str("\nOPTIONS:\n");
        render_flag_options_table(&mut out, &flag_opts);
    }

    // ENVIRONMENTS
    if !cmd.envs.is_empty() {
        out.push_str("\nENVIRONMENTS:\n");
        render_envs_table(&mut out, &cmd.envs);
    }

    out
}

pub fn usage_line(cmd: &Command, path: &[String], show_options_section: bool) -> String {
    let mut s = String::from("USAGE: ");
    s.push_str(&path.join(" "));
    let fos = &cmd.flag_options;
    let has_optional_opts = fos.iter().any(|f| !f.required);
    // Only show [OPTIONS] when user has optional flags/options
    if has_optional_opts || (show_options_section && !cmd.flag_options.is_empty() && has_optional_opts) {
        s.push_str(" [OPTIONS]");
    }
    // Required flags/options
    for f in fos {
        if !f.required { continue; }
        s.push(' ');
        s.push_str(&required_flag_usage(f));
    }
    // positional args
    for p in &cmd.positionals {
        s.push(' ');
        s.push_str(&positional_usage(p));
    }
    // subcommand
    if !cmd.subcommands.is_empty() {
        s.push_str(" <COMMAND>");
    }
    s
}

fn required_flag_usage(f: &FlagOption) -> String {
    let name = display_flag_name(f);
    let mut s = name;
    if !f.flag {
        s.push(' ');
        s.push_str(&notations_for_usage(f));
    }
    s
}

fn display_flag_name(f: &FlagOption) -> String {
    if !f.long_name.is_empty() { f.long_name.clone() } else { f.short_name.clone() }
}

fn notations_for_usage(f: &FlagOption) -> String {
    let notations = if f.notations.is_empty() {
        vec![f.id.to_uppercase()]
    } else { f.notations.clone() };
    let mut out = String::new();
    for (i, n) in notations.iter().enumerate() {
        if i > 0 { out.push(' '); }
        out.push('<');
        out.push_str(n);
        out.push('>');
    }
    if f.multiple_values || f.multiple_occurs {
        out.push_str("...");
    }
    out
}

pub fn get_displayed_flag_options(cmd: &Command, is_root: bool) -> Vec<FlagOption> {
    let mut out: Vec<FlagOption> = cmd.flag_options.iter().cloned().collect();
    // Add implicit help if not already present
    let has_help = out.iter().any(|f| f.long_name == "--help" || f.short_name == "-h");
    if !has_help {
        out.push(default_help_flag());
    }
    // Root: add --version
    if is_root {
        let has_version = out.iter().any(|f| f.long_name == "--version" || f.short_name == "-V");
        if !has_version {
            out.push(default_version_flag());
        }
    }
    out
}

fn render_positional_table(out: &mut String, list: &[&Positional]) {
    let items: Vec<(String, String)> = list.iter().map(|p| (positional_usage(p), p.describe.clone())).collect();
    render_two_cols(out, &items);
}

fn render_subcommands_table(out: &mut String, cmd: &Command) {
    let items: Vec<(String, String)> = cmd.subcommands.iter().map(|s| {
        let mut desc = s.describe.clone();
        if !s.aliases.is_empty() {
            if !desc.is_empty() { desc.push(' '); }
            desc.push_str(&format!("[aliases: {}]", s.aliases.join(", ")));
        }
        (s.name.clone(), desc)
    }).collect();
    render_two_cols(out, &items);
}

fn render_flag_options_table(out: &mut String, list: &[FlagOption]) {
    let items: Vec<(String, String)> = list.iter().map(|f| (flag_option_label(f), flag_option_describe(f))).collect();
    render_two_cols(out, &items);
}

fn render_envs_table(out: &mut String, list: &[EnvParam]) {
    let items: Vec<(String, String)> = list.iter().map(|e| {
        let mut label = e.id.clone();
        if e.required { label.push('*'); }
        (label, env_describe(e))
    }).collect();
    render_two_cols(out, &items);
}

fn env_describe(e: &EnvParam) -> String {
    let mut s = e.describe.clone();
    if let Some(ChoiceValue::Values(vals, _)) = &e.choice {
        if !s.is_empty() { s.push(' '); }
        s.push_str(&format!("[possible values: {}]", vals.join(", ")));
    }
    if let Some(DefaultValue::Value(v)) = &e.default {
        if !s.is_empty() { s.push(' '); }
        s.push_str(&format!("[default: {}]", v));
    }
    s
}

pub fn positional_usage(p: &Positional) -> String {
    let n = &p.notation;
    if p.required && p.multiple {
        format!("<{}>...", n)
    } else if p.required {
        format!("<{}>", n)
    } else if p.multiple {
        format!("[{}]...", n)
    } else {
        format!("[{}]", n)
    }
}

fn flag_option_label(f: &FlagOption) -> String {
    let short = f.short_name.clone();
    let long = f.long_name.clone();
    let mut s = String::new();
    if !short.is_empty() && !long.is_empty() {
        s.push_str(&short);
        s.push_str(", ");
        s.push_str(&long);
    } else if !long.is_empty() {
        s.push_str("    ");
        s.push_str(&long);
    } else if !short.is_empty() {
        s.push_str(&short);
    }
    if !f.flag {
        s.push(' ');
        s.push_str(&notations_for_label(f));
    }
    s
}

fn notations_for_label(f: &FlagOption) -> String {
    let notations = if f.notations.is_empty() {
        vec![f.id.to_uppercase()]
    } else { f.notations.clone() };
    if f.multiple_occurs {
        let mut out = String::new();
        out.push('[');
        out.push_str(&notations[0]);
        out.push(']');
        out.push_str("...");
        return out;
    }
    let mut out = String::new();
    for (i, n) in notations.iter().enumerate() {
        if i > 0 { out.push(' '); }
        out.push('<');
        out.push_str(n);
        out.push('>');
    }
    if f.multiple_values {
        out.push_str("...");
    }
    if f.terminated {
        let mut out2 = String::new();
        for (i, n) in notations.iter().enumerate() {
            if i > 0 { out2.push(' '); }
            out2.push('<');
            out2.push_str(n);
            out2.push('~');
            out2.push('>');
        }
        return out2;
    }
    out
}

fn flag_option_describe(f: &FlagOption) -> String {
    let mut s = f.describe.clone();
    if let Some(ChoiceValue::Values(vals, _)) = &f.choice {
        if !s.is_empty() { s.push(' '); }
        s.push_str(&format!("[possible values: {}]", vals.join(", ")));
    }
    if let Some(DefaultValue::Value(v)) = &f.default {
        if !s.is_empty() { s.push(' '); }
        s.push_str(&format!("[default: {}]", v));
    }
    s
}

fn render_two_cols(out: &mut String, items: &[(String, String)]) {
    let max = items.iter().map(|(a, _)| visual_len(a)).max().unwrap_or(0);
    for (a, b) in items {
        out.push_str("  ");
        out.push_str(a);
        if !b.is_empty() {
            let pad = max - visual_len(a);
            out.push_str(&" ".repeat(pad));
            out.push_str("  ");
            out.push_str(b);
        }
        out.push('\n');
    }
}

fn visual_len(s: &str) -> usize {
    s.chars().count()
}
